update public.places p set
 accessibility_info = d.info,
 tags = array(select tag from unnest(coalesce(p.tags,'{}'::text[]) ||
   array(select jsonb_array_elements_text(d.info->'searchTags'))) with ordinality as t(tag,n)
   group by tag order by min(n))
from incoming d where p.id=d.id and p.accessibility_info is null;
commit;
select count(*) as accessibility_records from public.places where accessibility_info is not null;
